package com.pavithran.aichat.model; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="conversations") public class Conversation { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) String deviceId; @Column(nullable=false) String title; @Column(nullable=false) Instant createdAt=Instant.now(); @Column(nullable=false) Instant updatedAt=Instant.now(); public UUID getId(){return id;} public String getDeviceId(){return deviceId;} public void setDeviceId(String v){deviceId=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void touch(){updatedAt=Instant.now();} }
